tion"}, {"id": "ff27edbd-192d-4fb0-ba39-053d5567106d", "type": "concept", "title": "Civil Constitution of the Clergy"}, {"id": "d2885ac3-2851-434a-9130-f0f0f45c8d23", "type": "concept", "title": "Disestablishment"}, {"id": "0ea5db42-32b7-4c30-9904-26bee4552ee6", "type": "concept", "title": "National churches"}, {"id": "c4ce4b69-2a50-4c59-a86a-53bb0dab75ac", "type": "concept", "title": "Ultramontanism"}, {"id": "31d9f7d2-5fb2-40db-82df-9ea810e8a491", "type": "concept", "title": "Kulturkampf"}, {"id": "dfadb089-9d67-437e-bd50-2bf69efa5910", "type": "concept", "title": "Church-state separation"}, {"id": "2e252222-cc53-4ea3-93f9-eb911350a48c", "type": "concept", "title": "Civil religion"}], "description": "Students learn how modern political orders reshaped church life."}, {"id": "ac7ba43a-9d90-4c46-98cb-c0a2e5aa1bd1", "type": "subtopic", "title": "Science and modern theology", "children": [{"id": "84fd13b0-9089-45d9-8550-435b4fdf4edc", "type": "concept", "title": "Darwin"}, {"id": "2ac30c39-db67-498a-8559-4cddbc5b16b1", "type": "concept", "title": "Biblical criticism"}, {"id": "d0c6c6ae-b141-4f47-b568-7d7195195175", "type": "concept", "title": "Liberal Protestantism"}, {"id": "406e8719-349e-4d0d-83ee-bf7e0f869eab", "type": "concept", "title": "Fundamentalism"}, {"id": "d15b462f-9262-4132-904d-53fdcfe4789c", "type": "concept", "title": "Modernism crisis"}, {"id": "7416fdba-e0af-46d3-9817-04bc3e7d2219", "type": "concept", "title": "Neo-orthodoxy"}, {"id": "b12dfc5a-909b-4090-bf69-933906ee8598", "type": "concept", "title": "Natural theology"}, {"id": "bba91568-a2b1-4548-96f1-e68ed13fc1ef", "type": "concept", "title": "Science and religion"}], "description": "The goal is to trace debates over reason, evidence, evolution, and belief."}]}, {"id": "3c79d75d-d7b3-4a98-82ce-907b90f260a3", "type": "topic", "title": "Revival, Evangelicalism, Methodism, and Global Protestant Missions", "description": "Evangelical and revival movements transformed Protestant Christianity and shaped