update public.learning_paths
set
  title = 'History of Christianity',
  goal = 'History of Christianity',
  summary = 'This syllabus treats Christianity as a historically changing, internally diverse, globally distributed tradition.',
  data = $hchrjson${"slug": "history-of-christianity", "title": "History of Christianity", "description": "This syllabus treats Christianity as a historically changing, internally diverse, globally distributed tradition.", "topics": [{"id": "6f3e8bbd-cbba-4948-ada3-d43ba01b70c2", "type": "topic", "title": "Studying the History of Christianity: Methods, Sources, and Periodization", "description": "This opening unit teaches students how historians study Christianity as a historical tradition rather than as a single timeless essence. Students learn to read primary sources, interpret institutions, and track change across regions, languages, empires, and communities.", "children": [{"id": "b648fa2d-383c-428f-9b50-5d57853a8515", "type": "subtopic", "title": "Historical method and source criticism", "children": [{"id": "5fd70e92-8095-4fa9-adbe-859d8a28bcef", "type": "concept", "title": "Primary sources"}, {"id": "86b38849-9b08-4d1a-be0d-68454e1b2657", "type": "concept", "title": "Secondary sources"}, {"id": "adc1e527-1d4d-4f71-ac3a-69e687195355", "type": "concept", "title": "Manuscripts"}, {"id": "eec28fbf-7743-4a8d-8c09-04b5728bbacd", "type": "concept", "title": "Material culture"}, {"id": "5a511dd6-705b-498d-b6a4-4654f49737c3", "type": "concept", "title": "Archaeology"}, {"id": "35dc4a9b-5c46-48ec-9fc9-72d01ed40c82", "type": "concept", "title": "Hagiography"}, {"id": "20a33710-80c7-4f2d-8c77-eb0a1a8d7cad", "type": "concept", "title": "Confessional sources"}, {"id": "921c5c54-0df6-4c06-88f2-955cbc420030", "type": "concept", "title": "Historical-critical method"}], "description": "Students learn how to ask historical questions about Christian texts, communities, institutions, and practices."}, {"id": "d9f79fec-6a02-4ada-b2f8-1e1477180916", "type": "subtopic", "title": "Periodization and geography", "children": [{"id": "bd2dbaba-f597-4952-81d3-c95f1686f554", "type": "concept", "title": "Antiquity"}, {"id": "e3f37a9b-c360-4907-b12c-4b79d35f4718", "type": "concept", "title": "Late antiquity"}, {"id": "4ec38183-de2d-40ca-82a5-c28679474767", "type": "concept", "title": "Medieval period"}, {"id": "956acd0a-6b46-488d-93c9-f9545a751944", "type": "concept", "title": "Reformation"}, {"id": "fbfeb162-1af8-4d9d-aed1-c423d771c289", "type": "concept", "title": "Early modernity"}, {"id": "d34cd36d-d85f-4bdf-9f29-d2ca417f6f46", "type": "concept", "title": "Modernity"}, {"id": "e3e9a94a-5324-4dca-acfd-0a922d413aa1", "type": "concept", "title": "Global South"}, {"id": "a5862000-55c9-4272-8bde-a166eddf6b7a", "type": "concept", "title": "Diaspora"}], "description": "The point is to understand why Christian history looks different depending on where and when one begins the story."}, {"id": "a3acd895-fb8d-4a77-9b54-dc66df56c646", "type": "subtopic", "title": "Categories and cautions", "children": [{"id": "df295470-83e4-4e21-bf77-6b462a7bc64c", "type": "concept", "title": "Doctrine"}, {"id": "e8d34d7e-585c-442d-abff-c6325fa20b65", "type": "concept", "title": "Practice"}, {"id": "702c300a-811c-4437-8d62-b55465a735f5", "type": "concept", "title": "Liturgy"}, {"id": "bcac88f2-e7a4-456d-adad-28f9580cf5c7", "type": "concept", "title": "Institution"}, {"id": "5bf39a2d-21ae-4f3d-b1a2-236670be0d13", "type": "concept", "title": "Popular religion"}, {"id": "c6bb72f4-b31f-4a7e-953b-d8c0d554d930", "type": "concept", "title": "Orthodoxy"}, {"id": "eb724c0c-ac50-49f1-a7f7-a8264705cc47", "type": "concept", "title": "Heresy"}, {"id": "5b6ef4fe-fc1a-4fca-84c1-c854df3ef203", "type": "concept", "title": "Colonial archive"}], "description": "Students learn to avoid flattening Christianity into one doctrine, one church, or one region."}]}, {"id": "786d0bb4-daf4-4e65-9059-da14fc28e9a2", "type": "topic", "title": "Jesus Movement, Jewish Contexts, and Early Christian Communities", "description": "Christianity began within Jewish worlds under Roman imperial rule. This unit grounds the course in Second Temple Judaism, the Jesus movement, early communities, and the formation of Christian identities.", "children": [{"id": "bf04156b-36b3-4e4c-9590-0d0be1c953cf", "type": "subtopic", "title": "Second Temple and Roman contexts", "children": [{"id": "04abd3e1-8d60-4db9-b27a-8136fe8d9dac", "type": "concept", "title": "Second Temple Judaism"}, {"id": "a9f712f7-571c-4ebf-b5f7-95b0904f0660", "type": "concept", "title": "Pharisees"}, {"id": "71703e62-1d9c-41e7-a9c7-5bb2270e5ae5", "type": "concept", "title": "Sadducees"}, {"id": "6c57de6e-4867-4208-aedf-ead833e04f61", "type": "concept", "title": "Essenes"}, {"id": "823d83f6-1855-4567-803c-6b49c6467fc6", "type": "concept", "title": "Apocalypticism"}, {"id": "d1599c2d-03ec-46ae-aefc-c7ae47f1ba7d", "type": "concept", "title": "Roman Judea"}, {"id": "e4fb323f-6982-45cc-8a54-e0f272a60358", "type": "concept", "title": "Temple"}, {"id": "c56ef3bd-8ad7-42d3-8dbb-fd9d5dc3b3b4", "type": "concept", "title": "Synagogue"}], "description": "Students learn the political, religious, and social setting in which Jesus and the first Jesus-followers lived."}, {"id": "603fdbcd-3561-491d-82a4-42c34fa17517", "type": "subtopic", "title": "Jesus and early communities", "children": [{"id": "1e58b898-b2ae-4a7a-a0e4-47de9d428b4f", "type": "concept", "title": "Kingdom of God"}, {"id": "f75ffc43-1afa-405e-aeaa-2c663a3857ec", "type": "concept", "title": "Disciples"}, {"id": "e53fdb46-4d47-4a72-bb0c-183549c913fb", "type": "concept", "title": "Crucifixion"}, {"id": "9f2a661e-51f5-4b28-b549-d78d09bcde48", "type": "concept", "title": "Resurrection claims"}, {"id": "f7440c8c-a6a7-4f4b-b35a-cb8226061bfd", "type": "concept", "title": "Jerusalem church"}, {"id": "497aec2f-e60b-4632-9c46-23febfd559a4", "type": "concept", "title": "Gentile mission"}, {"id": "b17132e3-fcb9-4f0f-9169-12326c50adf7", "type": "concept", "title": "House churches"}, {"id": "cd00ec2f-87c5-4fdf-af7a-9eed5fe6609c", "type": "concept", "title": "Charismatic authority"}], "description": "The goal is to distinguish the historical Jesus, remembered Jesus, and early community formations."}, {"id": "abe3389e-6000-46b7-9a22-4c39589aa575", "type": "subtopic", "title": "Paul and the New Testament world", "children": [{"id": "3f3fbf71-fce4-4571-93f7-e5cf376331b7", "type": "concept", "title": "Pauline letters"}, {"id": "89da9931-9cd5-471b-abb7-65ee0ce1ed90", "type": "concept", "title": "Gospels"}, {"id": "32e58a9d-4962-44ce-8022-f7014c0e6961", "type": "concept", "title": "Acts"}, {"id": "25aeb84f-3d2b-41e7-8406-48bbc9894148", "type": "concept", "title": "Catholic epistles"}, {"id": "ebb4a44e-4cce-43f0-ae56-71f575a089bd", "type": "concept", "title": "Revelation"}, {"id": "0f8627f3-357a-4c13-83ed-b38bed0ddcb2", "type": "concept", "title": "Canon formation"}, {"id": "634aabb4-4e3d-4b18-8778-a5524673184b", "type": "concept", "title": "Pseudepigraphy"}, {"id": "7bf32622-d816-45f9-aad5-6125169271b6", "type": "concept", "title": "Oral tradition"}], "description": "Students learn how early texts emerged from missionary, pastoral, liturgical, and polemical contexts."}]}, {"id": "0a6d4c3a-19b5-4170-87b6-7e66f243a69a", "type": "topic", "title": "Early Church and Roman Empire", "description": "The early church developed under imperial suspicion, local diversity, and growing institutional structure. Students learn how Christian communities negotiated persecution, apologetics, worship, authority, and social belonging.", "children": [{"id": "a81bc21e-38aa-448f-bcc3-a1260683d795", "type": "subtopic", "title": "Persecution and martyrdom", "children": [{"id": "eb2dadea-9cbf-4677-b988-ccac9fc581fe", "type": "concept", "title": "Nero"}, {"id": "6b26caad-b536-498a-a910-ba1f9e3e9c77", "type": "concept", "title": "Decius"}, {"id": "bf65a824-de99-45d4-9f71-b25d195a2a70", "type": "concept", "title": "Diocletian"}, {"id": "0c6a73e7-b200-46e1-89d5-0342531edcb2", "type": "concept", "title": "Martyr acts"}, {"id": "903a6da6-22e8-4a8d-b331-4ff8ffb502ac", "type": "concept", "title": "Confessors"}, {"id": "48a9da83-aca6-41cb-96cb-9661634e460c", "type": "concept", "title": "Apostasy"}, {"id": "c898e42f-215f-4394-bbda-858b4f360e76", "type": "concept", "title": "Lapsed Christians"}, {"id": "a1edb66c-f19e-4a47-b872-12a41b552322", "type": "concept", "title": "Cult of martyrs"}], "description": "Students examine how conflict with Roman power shaped Christian memory and identity."}, {"id": "d8ec02e9-4258-4d27-8e3d-cc9a467b175b", "type": "subtopic", "title": "Apologists and intellectual life", "children": [{"id": "c6f62827-f2b7-48e7-8a42-71f59a5ffa16", "type": "concept", "title": "Justin Martyr"}, {"id": "26d03e34-ddac-4ede-a101-c3b894408917", "type": "concept", "title": "Tertullian"}, {"id": "cd61f3e9-628a-4004-b620-0c3807d3cdb6", "type": "concept", "title": "Origen"}, {"id": "1190f013-bd86-439e-80d5-08bdd2c97266", "type": "concept", "title": "Athenagoras"}, {"id": "36954004-abba-42f9-9f2a-a635d0256533", "type": "concept", "title": "Logos theology"}, {"id": "704a8825-7ab2-4e23-92d4-3bc68e2f71a5", "type": "concept", "title": "Apologetics"}, {"id": "e2008d5c-fc1d-4028-9d85-b8f56c985bdd", "type": "concept", "title": "Allegorical interpretation"}, {"id": "2ca48b24-aad5-4958-84f5-5fa333daf1bb", "type": "concept", "title": "Christian Platonism"}], "description": "Students learn how Christians defended the movement in Greco-Roman philosophical and civic terms."}, {"id": "9f2a8ad2-1650-469c-9d5d-c4b73c013c54", "type": "subtopic", "title": "Worship and institutions", "children": [{"id": "b490259f-724c-47c4-9d59-658252623ef2", "type": "concept", "title": "Baptism"}, {"id": "85e1583a-9cb8-44d6-8b78-77ffe2ce6447", "type": "concept", "title": "Eucharist"}, {"id": "49d6cc75-bd01-4abf-8488-28650e95fdfe", "type": "concept", "title": "Bishops"}, {"id": "f0a61764-162b-4a68-a959-089c89659f91", "type": "concept", "title": "Presbyters"}, {"id": "5d91b08e-7cb0-487a-9f6c-30b0fcee1977", "type": "concept", "title": "Deacons"}, {"id": "b6edd241-56c6-4353-be94-0380c5485650", "type": "concept", "title": "Catechumenate"}, {"id": "4fbebd30-3c5a-43c0-8c89-98386fd6ca4a", "type": "concept", "title": "Creeds"}, {"id": "5001379e-8aad-4698-9b23-90bdeb85c1e8", "type": "concept", "title": "Liturgical calendar"}], "description": "The point is to see how ritual and leadership created durable communities."}]}, {"id": "fdedaaa2-fe15-4b2f-95d7-12e7a9a1a3f0", "type": "topic", "title": "Councils, Creeds, Doctrine, and Canon", "description": "Doctrinal Christianity took shape through controversy, council, imperial politics, and theological creativity. Students learn why debates over Christ, Trinity, scripture, and authority mattered historically.", "children": [{"id": "8c9b9d27-ecf7-4e15-b745-03ad8d9b6370", "type": "subtopic", "title": "Trinitarian and Christological debates", "children": [{"id": "f32edd7a-f27b-423f-8210-5b499373f2af", "type": "concept", "title": "Arian controversy"}, {"id": "2aeae015-04cd-4c34-9f0e-49b8426b3aa0", "type": "concept", "title": "Nicene Creed"}, {"id": "edc56e99-e16f-4435-962f-6aa8dc45579a", "type": "concept", "title": "Homoousios"}, {"id": "f48109be-2cde-46c8-8ed9-d626528142d3", "type": "concept", "title": "Cappadocian Fathers"}, {"id": "c529464e-413b-406c-a37a-f60aa651bed0", "type": "concept", "title": "Nestorian controversy"}, {"id": "47a9ad28-bbca-4a30-aab2-b8862ec6356c", "type": "concept", "title": "Monophysitism"}, {"id": "a82d1500-4161-4adf-8a28-8e03505a86f5", "type": "concept", "title": "Chalcedon"}, {"id": "3e24cfc1-d4be-489a-ba55-4b16f70db2a7", "type": "concept", "title": "Hypostatic union"}], "description": "Students learn the key controversies that produced classical Christian doctrine."}, {"id": "1c5687e6-4d9e-4ce8-82e0-4410cb487541", "type": "subtopic", "title": "Councils and ecclesial authority", "children": [{"id": "76f15ff7-82cf-4964-b814-80a79d0b56ac", "type": "concept", "title": "Council of Nicaea"}, {"id": "c705c1bd-f094-4d34-bcc3-5ef4f9e2d4b4", "type": "concept", "title": "Council of Constantinople"}, {"id": "b47e0562-4c42-4e9c-bc73-a84ea7712256", "type": "concept", "title": "Council of Ephesus"}, {"id": "f661cc1d-ef14-4686-8935-8eff6a5c477b", "type": "concept", "title": "Council of Chalcedon"}, {"id": "cd1c1a3b-a3f1-4ba1-b819-2505caae9e24", "type": "concept", "title": "Imperial patronage"}, {"id": "cebcb777-bd4a-41ba-8370-8e7b2b6ce200", "type": "concept", "title": "Anathema"}, {"id": "d9902771-069c-495e-afdb-e8f4858831a7", "type": "concept", "title": "Synods"}, {"id": "e3d42449-ba19-4fc2-81ae-4abe42d128fa", "type": "concept", "title": "Patriarchates"}], "description": "The goal is to understand councils as theological, political, and institutional events."}, {"id": "f4a5fba8-c419-4421-8c0e-43531fb691e8", "type": "subtopic", "title": "Canon and boundaries", "children": [{"id": "96124b1d-177d-4e2d-a98a-aa8aa7357933", "type": "concept", "title": "New Testament canon"}, {"id": "ebf23538-4e19-4f69-924a-c9f7340d714d", "type": "concept", "title": "Apostolic tradition"}, {"id": "2524dd14-beaf-459b-ba0a-6cac4720b030", "type": "concept", "title": "Rule of faith"}, {"id": "8e4152a2-b4c4-4939-8567-e7076878344e", "type": "concept", "title": "Gnosticism"}, {"id": "d4187bcd-070c-49f6-afec-99e5aece21d8", "type": "concept", "title": "Marcion"}, {"id": "0daf11af-d902-4fb4-8890-72b7839c5718", "type": "concept", "title": "Montanism"}, {"id": "7ef96516-7b67-490e-ab1c-498eb94d8b83", "type": "concept", "title": "Heresy"}, {"id": "33a4dce0-392f-4ca6-aa82-61cc4596cd60", "type": "concept", "title": "Orthodoxy"}], "description": "Students examine how communities distinguished authoritative texts and teachings from alternatives."}]}, {"id": "f5b010eb-ff63-4b2a-9756-14dea35070d1", "type": "topic", "title": "Late Antiquity: Constantine, Augustine, Bishops, and Empire", "description": "The conversion of Constantine and the Christianization of imperial institutions changed Christianity's social location. This unit studies the opportunities and tensions created by Christian empire.", "children": [{"id": "50b921e0-ca71-4c9e-8c88-c8b8dee9e845", "type": "subtopic", "title": "Constantinian transformation", "children": [{"id": "128a4259-6539-440b-97a0-b07df42b210f", "type": "concept", "title": "Edict of Milan"}, {"id": "1de0da17-5c1f-419e-843c-9c2661e9b3c2", "type": "concept", "title": "Constantine"}, {"id": "eb3e5810-1a18-43cc-83b3-93cb3a90b28d", "type": "concept", "title": "Theodosius"}, {"id": "873b0269-3220-4379-b665-adec86dec702", "type": "concept", "title": "Imperial church"}, {"id": "baf2e5cb-23cf-4406-8a3d-e3a90e0169b9", "type": "concept", "title": "Basilicas"}, {"id": "560001a4-f323-4189-a12a-08c52957309a", "type": "concept", "title": "Christian legislation"}, {"id": "41264bc2-0360-4132-a8f0-c1929bcebf23", "type": "concept", "title": "Paganism"}, {"id": "8e3070d1-63b4-40e4-8d53-fde7d7f064fd", "type": "concept", "title": "Religious coercion"}], "description": "Students learn how imperial patronage altered Christian institutions, buildings, law, and public status."}, {"id": "916afdb3-1ed5-4894-96c7-8683340ddaff", "type": "subtopic", "title": "Augustine and Latin Christianity", "children": [{"id": "c59eac61-96d5-4192-a414-fe27a05d86ca", "type": "concept", "title": "Confessions"}, {"id": "ca79623e-d910-4666-bcf7-54a716655f8c", "type": "concept", "title": "City of God"}, {"id": "e3c3899c-2e2d-4586-81c1-68d1b0be0bd7", "type": "concept", "title": "Original sin"}, {"id": "9b17b9aa-6f27-4dfa-9a2c-a28c5d62b94c", "type": "concept", "title": "Grace"}, {"id": "7659a758-cc2b-43dc-9684-5996a4d09152", "type": "concept", "title": "Donatist controversy"}, {"id": "777b6a95-d030-441a-b543-a83b87007f31", "type": "concept", "title": "Pelagian controversy"}, {"id": "cd6a269e-89ff-4ac0-ba5b-cfe7ccdc6b6c", "type": "concept", "title": "Just war"}, {"id": "ea84607b-6610-4240-a98f-2cfc996dbcac", "type": "concept", "title": "Memory and desire"}], "description": "Students examine Augustine as a bridge between ancient Christianity, medieval theology, and later Western debates."}, {"id": "83ca99b9-462f-4d11-80d7-33dcf7673a49", "type": "subtopic", "title": "Bishops and local power", "children": [{"id": "305f895f-c12c-458a-a5bf-789a5fb371fb", "type": "concept", "title": "Episcopal authority"}, {"id": "89124a29-36b6-4c7c-9451-526455474e91", "type": "concept", "title": "Charity"}, {"id": "12953f90-62c5-44c8-acbf-2ffdc6568e23", "type": "concept", "title": "Urban patronage"}, {"id": "91688ced-2a4b-4063-98ea-e11bcaef9e33", "type": "concept", "title": "Relics"}, {"id": "9db4647f-b2af-4383-8b52-d5323e1a36e4", "type": "concept", "title": "Pilgrimage"}, {"id": "b4084664-ae44-478a-93ea-0ea434862a4d", "type": "concept", "title": "Councils"}, {"id": "872cfc19-25ae-457b-b223-1069d8123eaf", "type": "concept", "title": "Church courts"}, {"id": "ffca3061-7eed-41c8-84f9-e20bb2004b15", "type": "concept", "title": "Pastoral care"}], "description": "The point is to understand the bishop as spiritual, civic, legal, and charitable leader."}]}, {"id": "0d50fcef-73cf-4065-8412-0ba3921bc023", "type": "topic", "title": "Monasticism, Asceticism, Mysticism, and Medieval Devotion", "description": "Monastic and ascetic movements reshaped Christian life by creating alternative forms of discipline, community, learning, and holiness. Students study monks, nuns, mystics, saints, and devotional practices.", "children": [{"id": "e8c72583-45f7-4991-a54f-11ea4b635fd1", "type": "subtopic", "title": "Monastic origins", "children": [{"id": "99e532c4-c927-4d53-83ae-543d960a4e03", "type": "concept", "title": "Desert Fathers"}, {"id": "7a98393f-0edd-4eaf-be5e-78cf3f34fced", "type": "concept", "title": "Desert Mothers"}, {"id": "3b828934-b7c9-4c09-adf1-2851d7e64fa0", "type": "concept", "title": "Anthony"}, {"id": "d3106a6f-0c61-4416-87d1-b88e1767c64a", "type": "concept", "title": "Pachomius"}, {"id": "67ae610d-5fc8-4d2f-951a-31439bdc3b24", "type": "concept", "title": "Benedict"}, {"id": "3f531a04-94b1-4f88-a2ad-0df758e60a73", "type": "concept", "title": "Rule of Benedict"}, {"id": "a494ced2-7eb6-4fdf-9b17-3f621dd03ada", "type": "concept", "title": "Cenobitic monasticism"}, {"id": "ca5e7