aries"}, {"id": "eafe4405-3864-4f82-abfa-5150ce15be0f", "type": "concept", "title": "Catechism"}, {"id": "11de6230-1535-469c-82e6-fee374047c57", "type": "concept", "title": "Baroque Catholicism"}, {"id": "5b97e8e0-9b14-400c-9559-3da444abe832", "type": "concept", "title": "Inquisition"}, {"id": "fcfc484e-bd20-4bee-ab43-1c37f476ed28", "type": "concept", "title": "Teresa of Avila"}], "description": "Students learn how Catholic institutions responded to Protestant critique and internal reform needs."}, {"id": "b8875f81-73e6-4866-82c1-37b8612816df", "type": "subtopic", "title": "Christianity and colonialism", "children": [{"id": "b3168c36-575a-44a5-b7f8-8ec68ac9a291", "type": "concept", "title": "Spanish missions"}, {"id": "cceafa46-e07c-465d-af3b-c7ffd759a62d", "type": "concept", "title": "Portuguese padroado"}, {"id": "2e186b58-5766-4d4d-be58-f84c3ec63acb", "type": "concept", "title": "Franciscans"}, {"id": "24eeba56-3626-44ba-936c-f9dc84d9bf74", "type": "concept", "title": "Dominicans"}, {"id": "66be47c5-797f-4053-a0fd-c12799a7165e", "type": "concept", "title": "Jesuits"}, {"id": "984c401e-0524-4a28-83e6-2f398c3af508", "type": "concept", "title": "Encomienda"}, {"id": "aacdd178-0fd2-4078-aece-6c5b6832af12", "type": "concept", "title": "Forced conversion"}, {"id": "e9b0c013-92e8-47ba-af39-f9da2f2f27f6", "type": "concept", "title": "Syncretism"}], "description": "Students examine how mission and empire overlapped in the Americas, Africa, and Asia."}, {"id": "caaf3f0f-7293-4c4c-ae4e-edc42f0ac205", "type": "subtopic", "title": "Local reception and agency", "children": [{"id": "6ccc62bb-a6c3-4d5f-821f-1f919464c30b", "type": "concept", "title": "Indigenous Christianity"}, {"id": "44a833b3-b260-4a91-9e5d-bd088fb3dacd", "type": "concept", "title": "African Christianity"}, {"id": "5a58f44d-8843-4a6d-8c54-c089b56d8d15", "type": "concept", "title": "Asian Christianity"}, {"id": "6a7c62fb-063c-4ce8-b399-ecd0d775d9e0", "type": "concept", "title": "Inculturation"}, {"id": "4829bd38