 Revolution"}, {"id": "ff27edbd-192d-4fb0-ba39-053d5567106d", "type": "concept", "title": "Civil Constitution of the Clergy"}, {"id": "d2885ac3-2851-434a-9130-f0f0f45c8d23", "type": "concept", "title": "Disestablishment"}, {"id": "0ea5db42-32b7-4c30-9904-26bee4552ee6", "type": "concept", "title": "National churches"}, {"id": "c4ce4b69-2a50-4c59-a86a-53bb0dab75ac", "type": "concept", "title": "Ultramontanism"}, {"id": "31d9f7d2-5fb2-40db-82df-9ea810e8a491", "type": "concept", "title": "Kulturkampf"}, {"id": "dfadb089-9d67-437e-bd50-2bf69efa5910", "type": "concept", "title": "Church-state separation"}, {"id": "2e252222-cc53-4ea3-93f9-eb911350a48c", "type": "concept", "title": "Civil religion"}], "description": "Students learn how modern political orders reshaped church life."}, {"id": "ac7ba43a-9d90-4c46-98cb-c0a2e5aa1bd1", "type": "subtopic", "title": "Science and modern theology", "children": [{"id": "84fd13b0-9089-45d9-8550-435b4fdf4edc", "type": "concept", "title": "Darwin"}, {"id": "2ac30c39-db67-498a-8559-4cddbc5b16b1", "type": "concept", "title": "Biblical criticism"}, {"id": "d0c6c6ae-b141-4f47-b568-7d7195195175", "type": "concept", "title": "Liberal Protestantism"}, {"id": "406e8719-349e-4d0d-83ee-bf7e0f869eab", "type": "concept", "title": "Fundamentalism"}, {"id": "d15b462f-9262-4132-904d-53fdcfe4789c", "type": "concept", "title": "Modernism crisis"}, {"id": "7416fdba-e0af-46d3-9817-04bc3e7d2219", "type": "concept", "title": "Neo-orthodoxy"}, {"id": "b12dfc5a-909b-4090-bf69-933906ee8598", "type": "concept", "title": "Natural theology"}, {"id": "bba91568-a2b1-4548-96f1-e68ed13fc1ef", "type": "concept", "title": "Science and religion"}], "description": "The goal is to trace debates over reason, evidence, evolution, and belief."}]}, {"id": "3c79d75d-d7b3-4a98-82ce-907b90f260a3", "type": "topic", "title": "Revival, Evangelicalism, Methodism, and Global Protestant Missions", "description": "Evangelical and revival movements transformed Protestant Christianity and shaped modern missions, reform movements, and global networks. Students study revival as both spiritual renewal and social force.", "children": [{"id": "d579e0c7-5413-45d1-b4e4-04a2bf14dbd6", "type": "subtopic", "title": "Pietism and Methodism", "children": [{"id": "1d727fbe-92a0-442e-9939-3c524063567c", "type": "concept", "title": "Pietism"}, {"id": "41fa52b7-79b4-4062-a35d-8a0bd4fad1fd", "type": "concept", "title": "Moravians"}, {"id": "f8f36b6d-b535-4015-bbda-c1747428584b", "type": "concept", "title": "John Wesley"}, {"id": "becf2ae8-8a63-4055-99cd-298cbaa452d0", "type": "concept", "title": "Charles Wesley"}, {"id": "ecac2314-1e02-4269-9362-b1bc3f5c04b5", "type": "concept", "title": "Methodism"}, {"id": "16f2dadd-b543-43a9-b9dc-44ff084ff9b1", "type": "concept", "title": "Class meetings"}, {"id": "21ef0da3-f6bd-4c8e-b442-dd5a6f9b40f0", "type": "concept", "title": "Holiness"}, {"id": "a6e0ea87-b082-4ffa-8b8c-36e8c857dbee", "type": "concept", "title": "Assurance"}], "description": "Students learn how renewal movements emphasized conversion, discipline, small groups, and heartfelt piety."}, {"id": "542a7acc-0800-4c5a-8ec4-47dc9d155c97", "type": "subtopic", "title": "Awakenings and revivalism", "children": [{"id": "616a9d17-4f38-4302-b82f-f65ad1c23f43", "type": "concept", "title": "First Great Awakening"}, {"id": "aa4db9a3-ef89-4a14-9b02-934192f1d3dc", "type": "concept", "title": "Second Great Awakening"}, {"id": "162073cd-f951-4134-93e3-12fffe543f25", "type": "concept", "title": "Jonathan Edwards"}, {"id": "b2a4496e-5616-4e0b-8e6f-a5210b897511", "type": "concept", "title": "George Whitefield"}, {"id": "06d5b248-aaaf-462c-a374-fb51d1919791", "type": "concept", "title": "Charles Finney"}, {"id": "c6293e1f-ae54-4a2c-9aa5-daa05a6f9942", "type": "concept", "title": "Camp meetings"}, {"id": "96dd5d70-4506-41e1-b93f-251ea0414b56", "type": "concept", "title": "Conversion narrative"}, {"id": "bace72b8-f41e-413b-9168-f736773f3bd4", "type": "concept", "title": "New measures"}]